<?php $title="New Service";require "includes/header.php";$cs=$conn->query("SELECT id,name FROM customers");$bs=$conn->query("SELECT id,name FROM bicycles");if($_SERVER["REQUEST_METHOD"]==="POST"){$s=$conn->prepare("INSERT INTO service(customer_id,bicycle_id,service_type,status,service_date,cost) VALUES(?,?,?,?,?,?)");$c=(int)$_POST["customer_id"];$b=(int)$_POST["bicycle_id"];$cost=(float)$_POST["cost"];$s->bind_param("iisssd",$c,$b,$_POST["service_type"],$_POST["status"],$_POST["service_date"],$cost);$s->execute();go("service.php");}?><div class="card"><h2>New Service Job</h2><form method="post"><label>Customer</label><select name="customer_id"><?php while($x=$cs->fetch_assoc()):?><option value="<?=$x["id"]?>"><?=e($x["name"])?></option><?php endwhile;?></select><label>Bicycle</label><select name="bicycle_id"><?php while($x=$bs->fetch_assoc()):?><option value="<?=$x["id"]?>"><?=e($x["name"])?></option><?php endwhile;?></select><label>Service Type</label><input name="service_type"><label>Status</label><select name="status"><option>Scheduled</option><option>In Progress</option><option>Ready</option><option>Completed</option></select><label>Date</label><input type="date" name="service_date" value="<?=date("Y-m-d")?>"><label>Cost</label><input type="number" name="cost" step=".01" value="500"><button class="btn primary">Create Job</button></form></div><?php require "includes/footer.php";?>